for r in range(R):
 xs=[c for c in range(C) if g[r][c]==5];
 for a,b in zip(xs,xs[1:]):
  for c in range(a+1,b): out[r][c]=3
for c in range(C):
 ys=[r for r in range(R) if g[r][c]==5];
 for a,b in zip(ys,ys[1:]):
  for r in range(a+1,b): out[r][c]=3
print("\n".join(" ".join(map(str,r)) for r in out))'"
r=terminal(cmd, timeout=30)
print(r.get('output',''))

